/* message / ok */
static const uint8_t vector_message_ok[4u] = {
	0x02, 0x41, 0x00, 0x00,
};

static void test_message_ok(void **state)
{
	uint8_t     buf[4u];
	situ_msg_t  msg;
	situ_view_t view;

	(void)state;
	memcpy(buf, vector_message_ok, sizeof(buf));
	situ_msg_init(&msg, buf, 4u);
	assert_int_equal(fzn_status_message_view(&msg, 0, 4u, &view), SITU_OK);
	assert_int_equal(fzn_status_message_validate(view), SITU_OK);

	/* Every value written back through its own setter must reproduce the
	 * bytes it came from. This is what catches a layout change. */
	fzn_status_message_family_set(view, fzn_status_message_family_get(view));
	fzn_status_message_type_set(view, fzn_status_message_type_get(view));
	fzn_status_message_code_set(view, fzn_status_message_code_get(view));
	fzn_status_message_why_len_set(&msg, view, fzn_status_message_why_len_get(view));
	assert_memory_equal(buf, vector_message_ok, sizeof(buf));
}

